globalThis.__MYX_ASSETS__ = {"/":{"body":"<!DOCTYPE html>\n<html lang=\"fa\" dir=\"rtl\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>MYX panel | ساخت کانفیگ</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\n  <link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;500;700;800&display=swap\" rel=\"stylesheet\" />\n  <link rel=\"stylesheet\" href=\"style.css\" />\n  <script src=\"https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js\" defer></script>\n</head>\n<body>\n  <header>\n    <div class=\"brand\">\n      <span class=\"brand-mark\">M</span>\n      <span class=\"brand-name\">MYX <b>panel</b></span>\n    </div>\n    <div class=\"hero-badge\"><span></span> سریع، خصوصی و آماده اتصال</div>\n    <h1>کانفیگت را بساز.<br/><em>همین حالا وصل شو.</em></h1>\n    <p class=\"subtitle\">تجربه‌ای ساده برای ساخت کانفیگ‌های Xray و Cloudflare Worker<br/>بدون پیچیدگی، بدون ارسال داده به سرور دیگری.</p>\n    <div class=\"hero-features\">\n      <span>☁️ پشتیبانی Cloudflare</span>\n      <span>📱 اتصال با QR Code</span>\n      <span>🔒 خصوصی و امن</span>\n    </div>\n  </header>\n\n  <main>\n    <!-- ============ ستون فرم ============ -->\n    <div class=\"col\">\n      <section class=\"card\">\n        <div class=\"step-title\"><span class=\"step-num\">۱</span> انتخاب قالب کانفیگ</div>\n        <p class=\"hint\">با انتخاب قالب، همه تنظیمات فنی به‌صورت خودکار انجام می‌شود.</p>\n        <div class=\"presets\">\n          <button class=\"preset worker-preset\" id=\"workerPreset\" type=\"button\">\n            <span class=\"preset-name\">☁️ Cloudflare Worker</span>\n            <span class=\"preset-desc\" id=\"workerPresetDesc\">اتصال به همین ورکر/پیجز (بدون VPS) — اگر روی Cloudflare باز شده باشد، خودکار پر می‌شود</span>\n          </button>\n          <button class=\"preset\" data-preset=\"vless-reality\">\n            <span class=\"preset-name\">VLESS + Reality</span>\n            <span class=\"preset-desc\">پیشنهادی · پایدارترین، بدون نیاز به دامنه</span>\n          </button>\n          <button class=\"preset\" data-preset=\"vless-ws-tls\">\n            <span class=\"preset-name\">VLESS + WS + TLS</span>\n            <span class=\"preset-desc\">مناسب استفاده پشت CDN (مثل Cloudflare)</span>\n          </button>\n          <button class=\"preset\" data-preset=\"trojan-ws-tls\">\n            <span class=\"preset-name\">Trojan + WS + TLS</span>\n            <span class=\"preset-desc\">ساده و سازگار، پشت CDN</span>\n          </button>\n          <button class=\"preset\" data-preset=\"vmess-ws-tls\">\n            <span class=\"preset-name\">VMess + WS + TLS</span>\n            <span class=\"preset-desc\">سازگاری بیشتر با کلاینت‌های قدیمی</span>\n          </button>\n        </div>\n      </section>\n\n      <section class=\"card\">\n        <div class=\"step-title\"><span class=\"step-num\">۲</span> مشخصات سرور</div>\n        <div class=\"grid\">\n          <label>\n            <span>پروتکل</span>\n            <select id=\"protocol\">\n              <option value=\"vless\">VLESS</option>\n              <option value=\"vmess\">VMess</option>\n              <option value=\"trojan\">Trojan</option>\n            </select>\n          </label>\n          <label>\n            <span>نام کانفیگ (Remark)</span>\n            <input id=\"remark\" type=\"text\" placeholder=\"MyServer\" value=\"MyServer\" />\n          </label>\n          <label class=\"full\">\n            <span>آدرس سرور <b class=\"req\">*</b></span>\n            <input id=\"address\" type=\"text\" placeholder=\"مثلاً 1.2.3.4 یا server.example.com\" dir=\"ltr\" />\n          </label>\n          <label>\n            <span>پورت</span>\n            <input id=\"port\" type=\"number\" value=\"443\" min=\"1\" max=\"65535\" dir=\"ltr\" />\n          </label>\n          <label>\n            <span id=\"idLabel\">UUID <b class=\"req\">*</b></span>\n            <div class=\"row\">\n              <input id=\"uuid\" type=\"text\" placeholder=\"UUID\" dir=\"ltr\" />\n              <button type=\"button\" id=\"genUuid\" class=\"btn small ghost\" title=\"تولید UUID تصادفی\">🎲</button>\n            </div>\n          </label>\n        </div>\n\n        <details id=\"advanced\">\n          <summary>⚙️ تنظیمات پیشرفته <span class=\"summary-hint\">(با قالب بالا خودکار پر می‌شود)</span></summary>\n\n          <h3>اتصال و امنیت</h3>\n          <div class=\"grid\">\n            <label>\n              <span>نوع شبکه (Transport)</span>\n              <select id=\"network\">\n                <option value=\"tcp\">TCP</option>\n                <option value=\"ws\">WebSocket</option>\n                <option value=\"httpupgrade\">HTTPUpgrade</option>\n                <option value=\"grpc\">gRPC</option>\n              </select>\n            </label>\n            <label>\n              <span>Security</span>\n              <select id=\"security\">\n                <option value=\"none\">none</option>\n                <option value=\"tls\">TLS</option>\n                <option value=\"reality\">REALITY</option>\n              </select>\n            </label>\n            <label id=\"encryptionWrap\">\n              <span>Encryption (فقط VLESS)</span>\n              <select id=\"encryption\">\n                <option value=\"none\">none</option>\n                <option value=\"aes-128-gcm\">aes-128-gcm</option>\n                <option value=\"chacha20-poly1305\">chacha20-poly1305</option>\n              </select>\n            </label>\n            <label id=\"flowWrap\">\n              <span>Flow</span>\n              <select id=\"flow\">\n                <option value=\"\">بدون flow</option>\n                <option value=\"xtls-rprx-vision\">xtls-rprx-vision</option>\n              </select>\n            </label>\n            <label>\n              <span>Mux</span>\n              <select id=\"mux\">\n                <option value=\"off\">خاموش</option>\n                <option value=\"on\">روشن (۸ کانال)</option>\n              </select>\n            </label>\n          </div>\n\n          <div id=\"tlsBlock\">\n            <h3 id=\"tlsTitle\">تنظیمات TLS</h3>\n            <div class=\"grid\">\n              <label>\n                <span>SNI</span>\n                <input id=\"sni\" type=\"text\" placeholder=\"example.com\" dir=\"ltr\" />\n              </label>\n              <label>\n                <span>ALPN</span>\n                <select id=\"alpn\">\n                  <option value=\"\">خالی</option>\n                  <option value=\"h2,http/1.1\">h2,http/1.1</option>\n                  <option value=\"h2\">h2</option>\n                  <option value=\"http/1.1\">http/1.1</option>\n                </select>\n              </label>\n              <label>\n                <span>Fingerprint</span>\n                <select id=\"fingerprint\">\n                  <option value=\"chrome\">chrome</option>\n                  <option value=\"firefox\">firefox</option>\n                  <option value=\"safari\">safari</option>\n                  <option value=\"ios\">ios</option>\n                  <option value=\"android\">android</option>\n                  <option value=\"edge\">edge</option>\n                  <option value=\"random\">random</option>\n                  <option value=\"\">بدون fp</option>\n                </select>\n              </label>\n              <label>\n                <span>Allow Insecure</span>\n                <select id=\"allowInsecure\">\n                  <option value=\"false\">خیر</option>\n                  <option value=\"true\">بله</option>\n                </select>\n              </label>\n            </div>\n          </div>\n\n          <div class=\"grid\" id=\"realityFields\" hidden>\n            <label>\n              <span>Public Key (pbk) <b class=\"req\">*</b></span>\n              <input id=\"pbk\" type=\"text\" placeholder=\"کلید عمومی Reality\" dir=\"ltr\" />\n            </label>\n            <label>\n              <span>Short ID (sid)</span>\n              <input id=\"sid\" type=\"text\" dir=\"ltr\" />\n            </label>\n            <label>\n              <span>Spider Path (spx)</span>\n              <input id=\"spx\" type=\"text\" value=\"/\" dir=\"ltr\" />\n            </label>\n            <label>\n              <span>Target (dest)</span>\n              <input id=\"dest\" type=\"text\" placeholder=\"www.microsoft.com:443\" dir=\"ltr\" />\n            </label>\n          </div>\n\n          <h3>تنظیمات شبکه</h3>\n          <div class=\"grid\">\n            <label class=\"wsField\">\n              <span>Host (برای WS / CDN مهم است)</span>\n              <input id=\"host\" type=\"text\" placeholder=\"example.com\" dir=\"ltr\" />\n            </label>\n            <label class=\"wsField\">\n              <span>Path</span>\n              <input id=\"path\" type=\"text\" value=\"/\" dir=\"ltr\" />\n            </label>\n            <label class=\"grpcField\" hidden>\n              <span>Service Name</span>\n              <input id=\"serviceName\" type=\"text\" placeholder=\"my-service\" dir=\"ltr\" />\n            </label>\n          </div>\n\n          <h3>وارد کردن لینک موجود</h3>\n          <div class=\"import-box\">\n            <input id=\"importLink\" type=\"text\" placeholder=\"لینک vless:// یا vmess:// یا trojan:// را اینجا بچسبانید\" dir=\"ltr\" />\n            <button type=\"button\" class=\"btn ghost\" id=\"doImport\">وارد کردن</button>\n          </div>\n          <p class=\"hint\" id=\"importMsg\"></p>\n        </details>\n      </section>\n    </div>\n\n    <!-- ============ ستون خروجی ============ -->\n    <div class=\"col\">\n      <section class=\"card sticky\">\n        <div class=\"step-title\"><span class=\"step-num\">۳</span> دریافت کانفیگ</div>\n\n        <div id=\"status\" class=\"status warn\">برای ساخت کانفیگ، آدرس سرور و UUID را وارد کنید.</div>\n\n        <div class=\"tabs\">\n          <button class=\"tab active\" data-tab=\"link\">📱 لینک و QR</button>\n          <button class=\"tab\" data-tab=\"json\">📄 JSON</button>\n          <button class=\"tab\" data-tab=\"sub\">🔗 Sub</button>\n        </div>\n\n        <div class=\"tab-panel active\" id=\"tab-link\">\n          <div class=\"qr-wrap\"><div id=\"qr\"></div></div>\n          <p class=\"hint center\">با اپ کلاینت (v2rayNG / Hiddify / Streisand) این QR را اسکن کنید یا لینک را کپی کنید.</p>\n          <pre id=\"linkOut\" class=\"link-out\" dir=\"ltr\"></pre>\n          <div class=\"actions\">\n            <button class=\"btn\" id=\"copyLink\">📋 کپی لینک</button>\n          </div>\n        </div>\n\n        <div class=\"tab-panel\" id=\"tab-json\">\n          <pre id=\"jsonOut\" dir=\"ltr\"></pre>\n          <div class=\"actions\">\n            <button class=\"btn\" id=\"copyJson\">📋 کپی JSON</button>\n            <button class=\"btn ghost\" id=\"dlJson\">⬇️ دانلود config.json</button>\n          </div>\n        </div>\n\n        <div class=\"tab-panel\" id=\"tab-sub\">\n          <p class=\"hint\">خروجی Base64 برای ساخت لینک سابسکریپشن. می‌توانید آن را دانلود و در همین سایت Netlify منتشر کنید.</p>\n          <pre id=\"subOut\" dir=\"ltr\"></pre>\n          <div class=\"actions\">\n            <button class=\"btn\" id=\"copySub\">📋 کپی Base64</button>\n            <button class=\"btn ghost\" id=\"dlSub\">⬇️ دانلود sub.txt</button>\n          </div>\n        </div>\n      </section>\n\n      <section class=\"card guide\">\n        <details>\n          <summary>❓ چطور وصل شوم؟</summary>\n          <ol>\n            <li>اگر پروژه را روی <b>Cloudflare Pages/Workers</b> باز کرده‌اید، قالب <b>☁️ Cloudflare Worker</b> را انتخاب کنید؛ آدرس، مسیر و UUID خودکار پر می‌شود و کانفیگ واقعاً به همین ورکر وصل می‌شود.</li>\n            <li>اگر سرور Xray روی VPS دارید، قالب <b>VLESS + Reality</b> را انتخاب و مشخصات سرورتان را وارد کنید.</li>\n            <li>روی گوشی: اپ <b>v2rayNG</b> (اندروید) یا <b>Hiddify / Streisand</b> (iOS) → گزینه <i>Add config from QR / Clipboard</i>.</li>\n            <li>روی کامپیوتر: <b>v2rayN / Hiddify / Nekoray</b> → درج لینک از کلیپ‌بورد یا وارد کردن فایل JSON.</li>\n            <li>سابسکریپشن روی Cloudflare: آدرس <code>/sub</code> را در کلاینت اضافه کنید. روی هاست استاتیک: فایل <code>sub.txt</code> را در ریشه سایت بگذارید و آدرس آن را وارد کنید.</li>\n          </ol>\n          <p class=\"hint\">⚠️ Netlify فقط پنل سازنده کانفیگ را میزبانی می‌کند و پروکسی اجرا نمی‌کند. برای «کانفیگ وصل بدون VPS» از همین پروژه روی Cloudflare Pages/Workers استفاده کنید. کانفیگ‌های Worker از UDP پشتیبانی نمی‌کنند.</p>\n        </details>\n      </section>\n    </div>\n  </main>\n\n  <div id=\"toast\" class=\"toast\" hidden>کپی شد ✔</div>\n\n  <footer><b>MYX panel</b><span>•</span> سریع و ساده<span>•</span> داده‌ها فقط در مرورگر شماست</footer>\n\n  <script src=\"app.js\"></script>\n</body>\n</html>\n","type":"text/html; charset=utf-8"},"/style.css":{"body":":root {\n  --bg: #070a14;\n  --card: rgba(18, 23, 43, .76);\n  --card-solid: #12172b;\n  --field: #11172c;\n  --border: rgba(164, 177, 232, .16);\n  --border-strong: rgba(164, 177, 232, .28);\n  --text: #f1f4ff;\n  --muted: #a0a9c9;\n  --purple: #a68bfa;\n  --blue: #73a7ff;\n  --cyan: #5ce1e6;\n  --green: #45dfaa;\n  --amber: #ffcb70;\n  --radius: 22px;\n  font-size: 15px;\n}\n\n* { box-sizing: border-box; }\nhtml { scroll-behavior: smooth; }\n::selection { background: rgba(166, 139, 250, .35); color: #fff; }\n\nbody {\n  margin: 0;\n  min-height: 100vh;\n  font-family: \"Vazirmatn\", \"Segoe UI\", Tahoma, sans-serif;\n  background:\n    radial-gradient(800px 480px at 90% 0%, rgba(115, 167, 255, .14), transparent 65%),\n    radial-gradient(700px 500px at 5% 8%, rgba(166, 139, 250, .14), transparent 62%),\n    radial-gradient(600px 450px at 45% 100%, rgba(92, 225, 230, .06), transparent 65%),\n    var(--bg);\n  color: var(--text);\n  overflow-x: hidden;\n}\n\nbody::before {\n  content: \"\";\n  position: fixed; inset: 0; pointer-events: none; z-index: -1;\n  background-image:\n    linear-gradient(rgba(255,255,255,.018) 1px, transparent 1px),\n    linear-gradient(90deg, rgba(255,255,255,.018) 1px, transparent 1px);\n  background-size: 48px 48px;\n  mask-image: linear-gradient(to bottom, #000, transparent 80%);\n}\n\n/* ===== Brand / Hero ===== */\nheader { text-align: center; padding: 30px 18px 22px; position: relative; }\n.brand {\n  display: inline-flex; align-items: center; gap: 11px;\n  padding: 7px 8px 7px 18px; border-radius: 16px;\n  background: rgba(17, 22, 42, .72); border: 1px solid var(--border);\n  box-shadow: 0 10px 35px rgba(0,0,0,.25); backdrop-filter: blur(14px);\n  margin-bottom: 30px;\n}\n.brand-mark {\n  width: 40px; height: 40px; display: grid; place-items: center;\n  border-radius: 12px; font: 800 22px/1 \"Segoe UI\", sans-serif; color: white;\n  background: linear-gradient(135deg, var(--purple), #7562dd 50%, #548fee);\n  box-shadow: 0 6px 18px rgba(137, 110, 245, .35);\n}\n.brand-name {\n  direction: ltr; font: 700 20px/1.1 \"Segoe UI\", sans-serif; letter-spacing: -.4px; padding-left: 2px;\n}\n.brand-name b { font-weight: 400; color: var(--muted); }\n.hero-badge {\n  width: fit-content; margin: 0 auto 16px; padding: 7px 13px;\n  border-radius: 999px; background: rgba(69,223,170,.07); border: 1px solid rgba(69,223,170,.18);\n  color: #a6eed3; font-size: .77rem;\n}\n.hero-badge span {\n  display: inline-block; width: 7px; height: 7px; margin-left: 6px; border-radius: 50%;\n  background: var(--green); box-shadow: 0 0 12px var(--green); animation: pulse 2s infinite;\n}\n@keyframes pulse { 50% { opacity: .45; } }\nheader h1 {\n  margin: 0 0 18px; font-size: clamp(2rem, 4.6vw, 3.5rem); font-weight: 800; line-height: 1.45;\n  letter-spacing: -1px;\n}\nheader h1 em {\n  font-style: normal;\n  background: linear-gradient(100deg, #c1b1ff 5%, var(--blue) 50%, var(--cyan));\n  -webkit-background-clip: text; background-clip: text; color: transparent;\n}\n.subtitle { color: var(--muted); margin: 0; line-height: 2; font-size: .93rem; }\n.hero-features { display: flex; justify-content: center; gap: 10px; flex-wrap: wrap; margin-top: 24px; }\n.hero-features span {\n  background: rgba(18,23,43,.55); border: 1px solid var(--border); color: #bec6e3;\n  border-radius: 12px; padding: 8px 12px; font-size: .76rem; backdrop-filter: blur(10px);\n}\n\n/* ===== Layout / Cards ===== */\nmain {\n  display: grid; grid-template-columns: 1.05fr .95fr; gap: 22px;\n  max-width: 1220px; margin: 20px auto 12px; padding: 0 20px; align-items: start;\n}\n.col { display: flex; flex-direction: column; gap: 20px; min-width: 0; }\n.card {\n  position: relative;\n  background: linear-gradient(145deg, rgba(255,255,255,.035), transparent 45%), var(--card);\n  border: 1px solid var(--border); border-radius: var(--radius);\n  padding: 23px; box-shadow: 0 22px 55px rgba(0,0,0,.22); backdrop-filter: blur(20px);\n}\n.card::before {\n  content: \"\"; position: absolute; inset: 0 16% auto; height: 1px;\n  background: linear-gradient(90deg, transparent, rgba(255,255,255,.18), transparent);\n}\n.sticky { position: sticky; top: 18px; }\n.step-title { display: flex; align-items: center; gap: 12px; font-size: 1.08rem; font-weight: 700; margin-bottom: 14px; }\n.step-num {\n  width: 32px; height: 32px; flex: 0 0 32px; display: grid; place-items: center;\n  border-radius: 11px; color: #fff; font-size: .92rem;\n  background: linear-gradient(135deg, var(--purple), #6d79e8);\n  box-shadow: 0 5px 16px rgba(134,110,231,.25);\n}\n.card h3 { margin: 20px 0 12px; font-size: .88rem; color: var(--cyan); border-bottom: 1px dashed var(--border); padding-bottom: 8px; }\n.hint { color: var(--muted); font-size: .79rem; line-height: 1.95; margin: 0 0 14px; }\n.hint.center { text-align: center; margin-top: 12px; }\n.req { color: var(--amber); }\n\n/* ===== Presets ===== */\n.presets { display: grid; grid-template-columns: 1fr 1fr; gap: 11px; }\n.preset {\n  position: relative; overflow: hidden; text-align: right; cursor: pointer; font-family: inherit;\n  background: rgba(12,17,35,.62); border: 1px solid var(--border); color: var(--text);\n  border-radius: 16px; padding: 15px; display: flex; flex-direction: column; gap: 6px;\n  transition: transform .18s, border-color .18s, background .18s, box-shadow .18s;\n}\n.preset:hover { border-color: rgba(166,139,250,.6); transform: translateY(-3px); background: rgba(28,34,62,.8); }\n.preset.active {\n  border-color: var(--purple);\n  background: linear-gradient(135deg, rgba(166,139,250,.18), rgba(115,167,255,.07)), var(--field);\n  box-shadow: 0 0 0 1px rgba(166,139,250,.2) inset, 0 10px 25px rgba(0,0,0,.18);\n}\n.preset.active::after {\n  content: \"✓\"; position: absolute; top: 10px; left: 11px; width: 20px; height: 20px;\n  display: grid; place-items: center; border-radius: 50%; background: var(--purple); color: white; font-size: .7rem;\n}\n.preset-name { font-weight: 700; font-size: .91rem; direction: ltr; text-align: right; }\n.preset-desc { color: var(--muted); font-size: .73rem; line-height: 1.8; }\n.worker-preset {\n  grid-column: 1 / -1; border-color: rgba(255,180,80,.38);\n  background: linear-gradient(120deg, rgba(255,156,60,.14), rgba(166,139,250,.09)), rgba(20,22,40,.8);\n}\n.worker-preset .preset-name { color: #ffd496; }\n.worker-preset.active, .worker-preset:hover { border-color: #ffb450; box-shadow: 0 0 0 1px rgba(255,180,80,.18) inset; }\n.worker-preset.active::after { background: #edae57; }\n\n/* ===== Forms ===== */\n.grid { display: grid; grid-template-columns: 1fr 1fr; gap: 13px; }\n.grid .full { grid-column: 1 / -1; }\nlabel { display: flex; flex-direction: column; gap: 7px; min-width: 0; }\nlabel > span { font-size: .78rem; color: #aeb7d7; }\ninput, select {\n  width: 100%; background: var(--field); border: 1px solid var(--border); color: var(--text);\n  border-radius: 13px; padding: 12px 14px; font-size: .88rem; font-family: inherit;\n  outline: none; transition: border-color .18s, box-shadow .18s, background .18s;\n}\ninput::placeholder { color: #687394; }\ninput:hover, select:hover { border-color: var(--border-strong); }\ninput:focus, select:focus {\n  border-color: var(--purple); box-shadow: 0 0 0 4px rgba(166,139,250,.10); background: #141b33;\n}\ninput[dir=\"ltr\"] { text-align: left; }\nselect { cursor: pointer; }\n.row { display: flex; gap: 8px; }\n.row input { flex: 1; }\n\n/* ===== Buttons ===== */\n.btn {\n  border: none; border-radius: 13px; padding: 12px 19px; cursor: pointer;\n  background: linear-gradient(125deg, #9b80f3, #688eef); color: #fff;\n  font-size: .87rem; font-weight: 600; font-family: inherit;\n  box-shadow: 0 8px 20px rgba(110,103,224,.22); transition: transform .12s, filter .18s, box-shadow .18s;\n}\n.btn:hover { filter: brightness(1.1); box-shadow: 0 10px 25px rgba(110,103,224,.32); }\n.btn:active { transform: scale(.97); }\n.btn.small { padding: 10px 14px; }\n.btn.ghost { background: rgba(255,255,255,.035); border: 1px solid var(--border); color: #d4dbef; box-shadow: none; }\n.btn.ghost:hover { border-color: var(--purple); background: rgba(166,139,250,.07); }\nbutton:focus-visible, summary:focus-visible { outline: 2px solid var(--cyan); outline-offset: 3px; }\n\n/* ===== Details / Guide ===== */\ndetails { margin-top: 18px; border-top: 1px dashed var(--border); padding-top: 15px; }\nsummary { cursor: pointer; font-size: .88rem; font-weight: 600; color: #bdaaff; user-select: none; }\nsummary::marker { color: var(--purple); }\n.summary-hint { color: var(--muted); font-weight: 400; font-size: .73rem; }\n.guide details { margin-top: 0; border-top: none; padding-top: 0; }\n.guide ol { padding-inline-start: 20px; font-size: .82rem; line-height: 2.15; color: #cbd2ea; }\n.guide code { background: rgba(115,167,255,.09); border: 1px solid rgba(115,167,255,.13); color: #acc9ff; padding: 2px 7px; border-radius: 7px; direction: ltr; display: inline-block; }\n.import-box { display: flex; gap: 8px; }\n.import-box input { flex: 1; font-size: .79rem; }\n#importMsg.ok { color: var(--green); }\n#importMsg.err { color: var(--amber); }\n\n/* ===== Status / Tabs ===== */\n.status { border-radius: 14px; padding: 11px 14px; font-size: .81rem; line-height: 1.9; margin-bottom: 16px; border: 1px solid; }\n.status.ok { color: #8ce9c2; background: rgba(69,223,170,.07); border-color: rgba(69,223,170,.24); }\n.status.warn { color: #ffda96; background: rgba(255,203,112,.07); border-color: rgba(255,203,112,.23); }\n.tabs { display: flex; gap: 7px; margin-bottom: 18px; padding: 5px; border-radius: 15px; background: rgba(6,9,20,.5); border: 1px solid var(--border); }\n.tab {\n  flex: 1; border: none; background: transparent; color: var(--muted); border-radius: 11px;\n  padding: 10px 7px; cursor: pointer; font-family: inherit; font-size: .82rem; transition: all .2s;\n}\n.tab:hover { color: #e2e7f9; }\n.tab.active { color: #fff; background: linear-gradient(135deg, rgba(166,139,250,.32), rgba(115,167,255,.20)); box-shadow: 0 4px 14px rgba(0,0,0,.2); }\n.tab-panel { display: none; }\n.tab-panel.active { display: block; animation: fade .22s ease; }\n@keyframes fade { from { opacity: 0; transform: translateY(5px); } to { opacity: 1; transform: none; } }\n\n/* ===== Outputs / QR ===== */\npre {\n  background: rgba(5,8,18,.72); border: 1px solid var(--border); border-radius: 14px; padding: 15px;\n  overflow: auto; max-height: 400px; font-size: .77rem; line-height: 1.75;\n  direction: ltr; text-align: left; white-space: pre-wrap; word-break: break-all;\n  color: #bfcbf2; margin: 0 0 13px; font-family: Consolas, monospace;\n}\n.link-out { font-size: .72rem; color: #a9c7ff; }\n.actions { display: flex; gap: 10px; flex-wrap: wrap; }\n.qr-wrap {\n  position: relative; width: fit-content; min-width: 224px; min-height: 224px; margin: 4px auto 0;\n  background: #fff; border-radius: 20px; padding: 16px;\n  display: flex; align-items: center; justify-content: center;\n  box-shadow: 0 15px 45px rgba(0,0,0,.35), 0 0 0 6px rgba(255,255,255,.04);\n}\n#qr img, #qr canvas { display: block; border-radius: 5px; }\n.qr-empty { color: #424a64; font-size: .77rem; padding: 30px 10px; text-align: center; line-height: 1.8; }\n\n/* ===== Scrollbar / Toast / Footer ===== */\npre::-webkit-scrollbar { width: 7px; height: 7px; }\npre::-webkit-scrollbar-thumb { background: #303957; border-radius: 10px; }\n.toast {\n  position: fixed; bottom: 26px; left: 50%; transform: translateX(-50%); z-index: 10;\n  background: rgba(19,29,45,.95); border: 1px solid rgba(69,223,170,.35); color: #b3f4da;\n  font-weight: 600; font-size: .86rem; padding: 12px 25px; border-radius: 14px;\n  box-shadow: 0 15px 40px rgba(0,0,0,.45); backdrop-filter: blur(16px); animation: pop .22s ease;\n}\n@keyframes pop { from { transform: translate(-50%,10px); opacity: 0; } to { transform: translate(-50%,0); opacity: 1; } }\nfooter { display: flex; justify-content: center; align-items: center; gap: 9px; color: #7883a4; font-size: .75rem; padding: 28px 16px 35px; }\nfooter b { direction: ltr; color: #b5aacf; font-family: \"Segoe UI\", sans-serif; }\nfooter span { color: #454e69; }\n\n/* ===== Responsive ===== */\n@media (max-width: 980px) {\n  main { grid-template-columns: 1fr; max-width: 760px; }\n  .sticky { position: static; }\n}\n@media (max-width: 540px) {\n  header { padding: 20px 16px 16px; }\n  .brand { margin-bottom: 25px; }\n  header h1 { font-size: 2rem; }\n  .subtitle br { display: none; }\n  .hero-features { gap: 7px; }\n  .hero-features span { padding: 7px 9px; font-size: .7rem; }\n  main { padding: 0 12px; gap: 14px; margin-top: 12px; }\n  .col { gap: 14px; }\n  .card { padding: 17px; border-radius: 18px; }\n  .presets, .grid { grid-template-columns: 1fr; }\n  .import-box { flex-direction: column; }\n  .tab { font-size: .75rem; padding: 10px 4px; }\n}\n","type":"text/css; charset=utf-8"},"/app.js":{"body":"// ===== پنل ساخت کانفیگ Xray — کاملاً سمت کلاینت، مناسب Netlify =====\n\nconst $ = (id) => document.getElementById(id);\n\nconst fields = [\n  \"protocol\", \"remark\", \"address\", \"port\", \"uuid\", \"encryption\", \"flow\",\n  \"network\", \"security\", \"sni\", \"alpn\", \"fingerprint\", \"allowInsecure\",\n  \"pbk\", \"sid\", \"spx\", \"dest\", \"host\", \"path\", \"serviceName\", \"mux\",\n];\n\n// قالب‌های آماده — با یک کلیک همه تنظیمات فنی پر می‌شود\nconst PRESETS = {\n  \"vless-reality\": {\n    protocol: \"vless\", network: \"tcp\", security: \"reality\",\n    flow: \"xtls-rprx-vision\", encryption: \"none\", fingerprint: \"chrome\",\n    port: \"443\", path: \"/\", spx: \"/\", alpn: \"\", mux: \"off\",\n  },\n  \"vless-ws-tls\": {\n    protocol: \"vless\", network: \"ws\", security: \"tls\",\n    flow: \"\", encryption: \"none\", fingerprint: \"chrome\",\n    port: \"443\", path: \"/\", alpn: \"h2,http/1.1\", mux: \"off\",\n  },\n  \"trojan-ws-tls\": {\n    protocol: \"trojan\", network: \"ws\", security: \"tls\",\n    flow: \"\", fingerprint: \"chrome\",\n    port: \"443\", path: \"/\", alpn: \"h2,http/1.1\", mux: \"off\",\n  },\n  \"vmess-ws-tls\": {\n    protocol: \"vmess\", network: \"ws\", security: \"tls\",\n    flow: \"\", fingerprint: \"chrome\",\n    port: \"443\", path: \"/\", alpn: \"h2,http/1.1\", mux: \"off\",\n  },\n};\n\nfunction readForm() {\n  const v = {};\n  for (const f of fields) v[f] = $(f).value.trim();\n  v.port = parseInt(v.port || \"443\", 10);\n  return v;\n}\n\nfunction setField(id, value) {\n  if ($(id) && value !== undefined) $(id).value = value;\n}\n\nfunction randomUUID() {\n  if (crypto.randomUUID) return crypto.randomUUID();\n  const b = crypto.getRandomValues(new Uint8Array(16));\n  b[6] = (b[6] & 0x0f) | 0x40;\n  b[8] = (b[8] & 0x3f) | 0x80;\n  const h = [...b].map((x) => x.toString(16).padStart(2, \"0\")).join(\"\");\n  return `${h.slice(0,8)}-${h.slice(8,12)}-${h.slice(12,16)}-${h.slice(16,20)}-${h.slice(20)}`;\n}\n\nfunction isUUID(s) {\n  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(s);\n}\n\n// ============ ساخت streamSettings ============\nfunction buildStreamSettings(v) {\n  const ss = { network: v.network };\n\n  if (v.security === \"tls\") {\n    ss.security = \"tls\";\n    const tls = {};\n    if (v.sni) tls.serverName = v.sni;\n    if (v.alpn) tls.alpn = v.alpn.split(\",\");\n    if (v.fingerprint) tls.fingerprint = v.fingerprint;\n    if (v.allowInsecure === \"true\") tls.allowInsecure = true;\n    ss.tlsSettings = tls;\n  } else if (v.security === \"reality\") {\n    ss.security = \"reality\";\n    const r = { fingerprint: v.fingerprint || \"chrome\" };\n    if (v.sni) r.serverName = v.sni;\n    if (v.pbk) r.publicKey = v.pbk;\n    if (v.sid) r.shortId = v.sid;\n    if (v.spx) r.spiderX = v.spx;\n    ss.realitySettings = r;\n  }\n\n  if (v.network === \"ws\" || v.network === \"httpupgrade\") {\n    const w = {};\n    if (v.path) w.path = v.path;\n    if (v.host) w.headers = { Host: v.host };\n    ss[v.network === \"ws\" ? \"wsSettings\" : \"httpupgradeSettings\"] = w;\n  } else if (v.network === \"grpc\") {\n    ss.grpcSettings = { serviceName: v.serviceName || \"\", multiMode: false };\n  } else if (v.network === \"tcp\" && (v.host || (v.path && v.path !== \"/\"))) {\n    ss.tcpSettings = {\n      header: {\n        type: \"http\",\n        request: {\n          path: [v.path || \"/\"],\n          headers: v.host ? { Host: [v.host] } : {},\n        },\n      },\n    };\n  }\n\n  return ss;\n}\n\nfunction canUseFlow(v) {\n  return v.protocol === \"vless\" && v.network === \"tcp\" && (v.security === \"tls\" || v.security === \"reality\");\n}\n\n// ============ ساخت JSON کامل کلاینت Xray ============\nfunction buildXrayJson(v) {\n  const user = { id: v.uuid, level: 0 };\n  if (v.protocol === \"vless\") {\n    user.encryption = v.encryption || \"none\";\n    if (v.flow && canUseFlow(v)) user.flow = v.flow;\n  }\n\n  const outbound = {\n    protocol: v.protocol,\n    settings: { vnext: [{ address: v.address, port: v.port, users: [user] }] },\n    streamSettings: buildStreamSettings(v),\n  };\n  if (v.mux === \"on\") outbound.mux = { enabled: true, concurrency: 8 };\n\n  return {\n    log: { loglevel: \"warning\" },\n    inbounds: [\n      {\n        tag: \"socks-in\", port: 10808, listen: \"127.0.0.1\", protocol: \"socks\",\n        settings: { udp: true },\n        sniffing: { enabled: true, destOverride: [\"http\", \"tls\"] },\n      },\n      {\n        tag: \"http-in\", port: 10809, listen: \"127.0.0.1\", protocol: \"http\",\n        sniffing: { enabled: true, destOverride: [\"http\", \"tls\"] },\n      },\n    ],\n    outbounds: [\n      outbound,\n      { protocol: \"freedom\", tag: \"direct\" },\n      { protocol: \"blackhole\", tag: \"block\" },\n    ],\n    routing: {\n      domainStrategy: \"IPIfNonMatch\",\n      rules: [\n        { type: \"field\", ip: [\"geoip:private\"], outboundTag: \"direct\" },\n        { type: \"field\", domain: [\"geosite:private\"], outboundTag: \"direct\" },\n      ],\n    },\n  };\n}\n\n// ============ لینک اشتراک ============\nfunction buildShareLink(v) {\n  const remark = encodeURIComponent(v.remark || \"config\");\n  const p = new URLSearchParams();\n\n  if (v.protocol === \"vless\") {\n    p.set(\"encryption\", v.encryption || \"none\");\n    if (canUseFlow(v) && v.flow) p.set(\"flow\", v.flow);\n  }\n\n  if (v.security !== \"none\") {\n    p.set(\"security\", v.security);\n    if (v.sni) p.set(\"sni\", v.sni);\n    if (v.fingerprint) p.set(\"fp\", v.fingerprint);\n    if (v.security === \"tls\") {\n      if (v.alpn) p.set(\"alpn\", v.alpn);\n      if (v.allowInsecure === \"true\") p.set(\"allowInsecure\", \"1\");\n    }\n    if (v.security === \"reality\") {\n      if (v.pbk) p.set(\"pbk\", v.pbk);\n      if (v.sid) p.set(\"sid\", v.sid);\n      if (v.spx) p.set(\"spx\", v.spx);\n    }\n  }\n\n  p.set(\"type\", v.network);\n  if (v.network === \"ws\" || v.network === \"httpupgrade\") {\n    if (v.host) p.set(\"host\", v.host);\n    if (v.path) p.set(\"path\", v.path);\n  } else if (v.network === \"grpc\" && v.serviceName) {\n    p.set(\"serviceName\", v.serviceName);\n  }\n\n  const auth = v.protocol === \"trojan\" ? encodeURIComponent(v.uuid) : v.uuid;\n  return `${v.protocol}://${auth}@${v.address}:${v.port}?${p.toString()}#${remark}`;\n}\n\nfunction buildVmessLink(v) {\n  const tlsEnabled = v.security === \"tls\";\n  const obj = {\n    v: \"2\",\n    ps: v.remark || \"config\",\n    add: v.address,\n    port: String(v.port),\n    id: v.uuid,\n    aid: \"0\",\n    scy: \"auto\",\n    net: v.network,\n    type: \"none\",\n    host: v.network === \"ws\" || v.network === \"httpupgrade\" ? (v.host || \"\") : \"\",\n    path: v.network === \"ws\" || v.network === \"httpupgrade\" ? (v.path || \"\") : (v.network === \"grpc\" ? (v.serviceName || \"\") : \"\"),\n    tls: tlsEnabled ? \"tls\" : \"\",\n    sni: tlsEnabled ? (v.sni || \"\") : \"\",\n    alpn: tlsEnabled ? (v.alpn || \"\") : \"\",\n    fp: tlsEnabled ? (v.fingerprint || \"\") : \"\",\n  };\n  return `vmess://${b64EncodeUtf8(JSON.stringify(obj))}`;\n}\n\n// ============ Base64 سازگار با یونیکد ============\nfunction b64EncodeUtf8(str) {\n  const bytes = new TextEncoder().encode(str);\n  let bin = \"\";\n  for (const b of bytes) bin += String.fromCharCode(b);\n  return btoa(bin);\n}\nfunction b64DecodeUtf8(b64) {\n  const bin = atob(b64.replace(/-/g, \"+\").replace(/_/g, \"/\"));\n  const bytes = Uint8Array.from(bin, (c) => c.charCodeAt(0));\n  return new TextDecoder().decode(bytes);\n}\n\n// ============ اعتبارسنجی ============\nfunction validate(v) {\n  const errs = [];\n  if (!v.address) errs.push(\"آدرس سرور\");\n  if (!v.port || v.port < 1 || v.port > 65535) errs.push(\"پورت معتبر (۱ تا ۶۵۵۳۵)\");\n  if (!v.uuid) {\n    errs.push(v.protocol === \"trojan\" ? \"رمز (Password)\" : \"UUID\");\n  } else if (v.protocol !== \"trojan\" && !isUUID(v.uuid)) {\n    errs.push(\"UUID معتبر (با دکمه 🎲 بسازید)\");\n  }\n  if (v.security === \"reality\") {\n    if (!v.pbk) errs.push(\"Public Key (pbk) برای Reality\");\n    if (!v.sni) errs.push(\"SNI برای Reality\");\n  }\n  if (v.network === \"ws\" && !v.host) errs.push(\"Host برای WebSocket (در تنظیمات پیشرفته)\");\n  return errs;\n}\n\n// ============ QR ============\nfunction updateQR(text) {\n  const el = $(\"qr\");\n  el.innerHTML = \"\";\n  if (!text) {\n    el.innerHTML = '<div class=\"qr-empty\">کانفیگ کامل شود، QR اینجا نمایش داده می‌شود</div>';\n    return;\n  }\n  if (!window.QRCode) {\n    el.innerHTML = '<div class=\"qr-empty\">برای نمایش QR به اینترنت نیاز است؛ لینک را کپی کنید.</div>';\n    return;\n  }\n  new QRCode(el, {\n    text,\n    width: 190,\n    height: 190,\n    colorDark: \"#0b0e1a\",\n    colorLight: \"#ffffff\",\n    correctLevel: QRCode.CorrectLevel.M,\n  });\n}\n\n// ============ رندر اصلی ============\nfunction render() {\n  const v = readForm();\n\n  // نمایش/پنهان‌سازی فیلدها بر اساس انتخاب‌ها\n  $(\"encryptionWrap\").style.display = v.protocol === \"vless\" ? \"\" : \"none\";\n  $(\"flowWrap\").style.display = v.protocol === \"vless\" ? \"\" : \"none\";\n  $(\"idLabel\").innerHTML = v.protocol === \"trojan\" ? 'رمز (Password) <b class=\"req\">*</b>' : 'UUID <b class=\"req\">*</b>';\n\n  const isReality = v.security === \"reality\";\n  $(\"tlsBlock\").hidden = v.security === \"none\";\n  $(\"tlsTitle\").textContent = isReality ? \"تنظیمات REALITY\" : \"تنظیمات TLS\";\n  $(\"realityFields\").hidden = !isReality;\n\n  const wsLike = [\"ws\", \"httpupgrade\", \"tcp\"].includes(v.network);\n  document.querySelectorAll(\".wsField\").forEach((el) => (el.hidden = !wsLike));\n  document.querySelectorAll(\".grpcField\").forEach((el) => (el.hidden = v.network !== \"grpc\"));\n\n  // هایلایت قالب فعال؛ اگر اطلاعات همان ورکر باشد، کارت نارنجی Cloudflare انتخاب می‌شود\n  const activeKey = detectPreset(v);\n  const isWorker = !!workerInfo && v.protocol === \"vless\" && v.network === \"ws\" &&\n    v.address === workerInfo.host && v.host === workerInfo.host && v.path === workerInfo.path;\n  document.querySelectorAll(\".preset\").forEach((b) => {\n    b.classList.toggle(\"active\", !!activeKey && !isWorker && b.dataset.preset === activeKey);\n  });\n  $(\"workerPreset\").classList.toggle(\"active\", isWorker);\n\n  // اعتبارسنجی + وضعیت\n  const errs = validate(v);\n  const status = $(\"status\");\n  if (errs.length) {\n    status.className = \"status warn\";\n    status.textContent = \"⚠️ برای ساخت کانفیگ این موارد را کامل کنید: \" + errs.join(\"، \");\n    $(\"jsonOut\").textContent = \"\";\n    $(\"linkOut\").textContent = \"\";\n    $(\"subOut\").textContent = \"\";\n    updateQR(\"\");\n    return;\n  }\n  status.className = \"status ok\";\n  status.textContent = \"✅ کانفیگ آماده است — QR را اسکن کنید یا لینک را کپی کنید.\";\n\n  $(\"jsonOut\").textContent = JSON.stringify(buildXrayJson(v), null, 2);\n  const link = v.protocol === \"vmess\" ? buildVmessLink(v) : buildShareLink(v);\n  $(\"linkOut\").textContent = link;\n  $(\"subOut\").textContent = b64EncodeUtf8(link);\n  updateQR(link);\n}\n\nfunction detectPreset(v) {\n  for (const [key, p] of Object.entries(PRESETS)) {\n    if (v.protocol === p.protocol && v.network === p.network && v.security === p.security) return key;\n  }\n  return null;\n}\n\n// ============ وارد کردن لینک موجود ============\nfunction importLink() {\n  const msg = $(\"importMsg\");\n  const raw = $(\"importLink\").value.trim();\n  msg.className = \"hint\";\n  try {\n    if (raw.startsWith(\"vmess://\")) {\n      const obj = JSON.parse(b64DecodeUtf8(raw.slice(8)));\n      setField(\"protocol\", \"vmess\");\n      setField(\"address\", obj.add || \"\");\n      setField(\"port\", obj.port || \"443\");\n      setField(\"uuid\", obj.id || \"\");\n      setField(\"remark\", obj.ps || \"MyServer\");\n      setField(\"network\", obj.net || \"tcp\");\n      setField(\"security\", obj.tls ? \"tls\" : \"none\");\n      setField(\"host\", obj.host || \"\");\n      setField(\"path\", obj.path || \"/\");\n      setField(\"sni\", obj.sni || \"\");\n      setField(\"alpn\", obj.alpn || \"\");\n      if (obj.fp) setField(\"fingerprint\", obj.fp);\n      setField(\"serviceName\", obj.net === \"grpc\" ? (obj.path || \"\") : \"\");\n    } else if (raw.startsWith(\"vless://\") || raw.startsWith(\"trojan://\")) {\n      const u = new URL(raw);\n      setField(\"protocol\", u.protocol.replace(\":\", \"\"));\n      setField(\"uuid\", decodeURIComponent(u.username));\n      setField(\"address\", u.hostname);\n      setField(\"port\", u.port || \"443\");\n      setField(\"remark\", decodeURIComponent(u.hash.slice(1)) || \"MyServer\");\n      const q = u.searchParams;\n      setField(\"network\", q.get(\"type\") || \"tcp\");\n      setField(\"security\", q.get(\"security\") || \"none\");\n      setField(\"sni\", q.get(\"sni\") || \"\");\n      setField(\"host\", q.get(\"host\") || \"\");\n      setField(\"path\", q.get(\"path\") || \"/\");\n      setField(\"serviceName\", q.get(\"serviceName\") || \"\");\n      setField(\"encryption\", q.get(\"encryption\") || \"none\");\n      setField(\"flow\", q.get(\"flow\") || \"\");\n      setField(\"pbk\", q.get(\"pbk\") || \"\");\n      setField(\"sid\", q.get(\"sid\") || \"\");\n      setField(\"spx\", q.get(\"spx\") || \"/\");\n      setField(\"alpn\", q.get(\"alpn\") || \"\");\n      if (q.get(\"fp\")) setField(\"fingerprint\", q.get(\"fp\"));\n      setField(\"allowInsecure\", q.get(\"allowInsecure\") === \"1\" ? \"true\" : \"false\");\n    } else {\n      throw new Error(\"bad protocol\");\n    }\n    msg.textContent = \"✔ لینک با موفقیت وارد شد؛ فرم به‌روزرسانی شد.\";\n    msg.classList.add(\"ok\");\n    $(\"advanced\").open = true;\n  } catch {\n    msg.textContent = \"✖ لینک معتبر نیست. فقط لینک‌های vless:// vmess:// trojan:// پشتیبانی می‌شود.\";\n    msg.classList.add(\"err\");\n  }\n  render();\n}\n\n// ============ ابزارها ============\nfunction toast(msg) {\n  const t = $(\"toast\");\n  t.textContent = msg;\n  t.hidden = false;\n  clearTimeout(t._timer);\n  t._timer = setTimeout(() => (t.hidden = true), 1800);\n}\n\nasync function copyText(text, msg) {\n  if (!text) return;\n  try {\n    await navigator.clipboard.writeText(text);\n  } catch {\n    const ta = document.createElement(\"textarea\");\n    ta.value = text;\n    document.body.appendChild(ta);\n    ta.select();\n    document.execCommand(\"copy\");\n    ta.remove();\n  }\n  toast(msg);\n}\n\nfunction download(filename, content) {\n  if (!content) return;\n  const blob = new Blob([content], { type: \"text/plain;charset=utf-8\" });\n  const a = document.createElement(\"a\");\n  a.href = URL.createObjectURL(blob);\n  a.download = filename;\n  a.click();\n  URL.revokeObjectURL(a.href);\n}\n\n// ============ تشخیص و اتصال خودکار به Cloudflare Worker ============\nlet workerInfo = null;\n\nasync function detectWorker() {\n  try {\n    const res = await fetch(\"/info\", { headers: { accept: \"application/json\" } });\n    if (!res.ok) return;\n    const info = await res.json();\n    if (!info.uuid || !info.path || !info.host) return;\n    workerInfo = info;\n    $(\"workerPresetDesc\").textContent = `متصل به ${info.host} — کانفیگ واقعاً وصل، بدون VPS`;\n    applyWorkerConfig();\n  } catch {\n    // روی Netlify یا اجرای محلی: فقط تولید کانفیگ دستی\n  }\n}\n\nfunction applyWorkerConfig() {\n  const host = workerInfo?.host || location.hostname;\n  if (!workerInfo && (!host || [\"localhost\", \"127.0.0.1\"].includes(host))) {\n    toast(\"اول پروژه را روی Cloudflare اجرا کنید\");\n    return;\n  }\n  const info = workerInfo || { host, path: \"/vless\" };\n  setField(\"protocol\", \"vless\");\n  setField(\"network\", \"ws\");\n  setField(\"security\", \"tls\");\n  setField(\"flow\", \"\");\n  setField(\"encryption\", \"none\");\n  setField(\"fingerprint\", \"chrome\");\n  setField(\"alpn\", \"h2,http/1.1\");\n  setField(\"port\", \"443\");\n  setField(\"address\", info.host);\n  setField(\"host\", info.host);\n  setField(\"sni\", info.host);\n  setField(\"path\", info.path);\n  setField(\"remark\", \"CF-Worker\");\n  if (info.uuid) setField(\"uuid\", info.uuid);\n  render();\n  toast(\"کانفیگ همین ورکر ساخته شد ☁️✔\");\n}\n\n$(\"workerPreset\").addEventListener(\"click\", applyWorkerConfig);\n\n// ============ رویدادها ============\nfields.forEach((f) => $(f).addEventListener(\"input\", render));\n\ndocument.querySelectorAll(\".preset\").forEach((btn) => {\n  btn.addEventListener(\"click\", () => {\n    const p = PRESETS[btn.dataset.preset];\n    // مقادیر مخصوص قالب را اعمال می‌کنیم؛ Houst و SNI اگر خالی باشند با آدرس پر می‌شوند\n    for (const [k, val] of Object.entries(p)) setField(k, val);\n    if (p.security === \"tls\" && !$(\"sni\").value && $(\"host\").value) setField(\"sni\", $(\"host\").value);\n    render();\n    toast(\"قالب اعمال شد ✔\");\n  });\n});\n\n$(\"genUuid\").addEventListener(\"click\", () => {\n  setField(\"uuid\", randomUUID());\n  render();\n});\n\ndocument.querySelectorAll(\".tab\").forEach((tab) => {\n  tab.addEventListener(\"click\", () => {\n    document.querySelectorAll(\".tab\").forEach((t) => t.classList.remove(\"active\"));\n    document.querySelectorAll(\".tab-panel\").forEach((p) => p.classList.remove(\"active\"));\n    tab.classList.add(\"active\");\n    $(\"tab-\" + tab.dataset.tab).classList.add(\"active\");\n  });\n});\n\n$(\"copyJson\").addEventListener(\"click\", () => copyText($(\"jsonOut\").textContent, \"JSON کپی شد ✔\"));\n$(\"copyLink\").addEventListener(\"click\", () => copyText($(\"linkOut\").textContent, \"لینک کپی شد ✔\"));\n$(\"copySub\").addEventListener(\"click\", () => copyText($(\"subOut\").textContent, \"Base64 کپی شد ✔\"));\n$(\"dlJson\").addEventListener(\"click\", () => download(\"config.json\", $(\"jsonOut\").textContent));\n$(\"dlSub\").addEventListener(\"click\", () => download(\"sub.txt\", $(\"subOut\").textContent));\n$(\"doImport\").addEventListener(\"click\", importLink);\n$(\"importLink\").addEventListener(\"keydown\", (e) => { if (e.key === \"Enter\") { e.preventDefault(); importLink(); } });\n\n// کتابخانه QR مسیر defer دارد؛ بعد از لود یک‌بار رندر مجدد\nwindow.addEventListener(\"load\", render);\n\n// مقدار اولیه: قالب پیشنهادی + UUID تصادفی\nsetField(\"uuid\", randomUUID());\nfor (const [k, val] of Object.entries(PRESETS[\"vless-reality\"])) setField(k, val);\nrender();\ndetectWorker();\n","type":"application/javascript; charset=utf-8"}};
// Cloudflare Workers / Pages (Advanced mode) — VLESS over WebSocket + پنل استاتیک
// مسیرها:
//   /            → فایل‌های پنل (ASSETS)
//   /info        → مشخصات اتصال برای پر کردن خودکار پنل
//   /sub         → خروجی سابسکریپشن Base64
//   /vless (پیش‌فرض) → ارتقای WebSocket و اجرای پروتکل VLESS
//
// متغیرهای محیطی (Dashboard → Settings → Variables):
//   UUID    شناسه اتصال (پیش‌نهاد: مقدار تصادفی خودتان)
//   PATH    مسیر WebSocket، پیش‌فرض /vless
//   PROXYIP اختیاری: IP:port برای اتصال به مقصدهایی که خود Cloudflare هستند

import { connect } from "cloudflare:sockets";

const DEFAULT_UUID = "7c3d6f2a-9b41-4f5e-8a0c-2d91e6b4a735";

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const host = url.hostname;
    const uuid = (env.UUID || DEFAULT_UUID).toLowerCase();
    const wsPath = normalizePath(env.PATH || "/vless");

    if (url.pathname === "/info") {
      return jsonResponse({ uuid, path: wsPath, host });
    }

    if (url.pathname === "/sub") {
      const link = buildWorkerLink(host, uuid, wsPath);
      const body = btoa(String.fromCharCode(...new TextEncoder().encode(link + "\n")));
      return new Response(body, {
        headers: {
          "content-type": "text/plain; charset=utf-8",
          "cache-control": "no-store",
        },
      });
    }

    if (url.pathname === wsPath || url.pathname === wsPath + "/") {
      if ((request.headers.get("Upgrade") || "").toLowerCase() !== "websocket") {
        return new Response("VLESS WebSocket endpoint", { status: 200 });
      }
      return handleVless(request, uuid, env.PROXYIP || "");
    }

    // بقیه مسیرها → فایل‌های استاتیک پنل (Pages/Assets یا نسخه یک‌فایلی Wizard)
    if (env.ASSETS) return env.ASSETS.fetch(request);
    const embedded = serveEmbeddedAsset(url.pathname);
    if (embedded) return embedded;
    return new Response("Not found", { status: 404 });
  },
};

function serveEmbeddedAsset(pathname) {
  const assets = globalThis.__MYX_ASSETS__;
  if (!assets) return null;
  const asset = assets[pathname] || (pathname === "/index.html" ? assets["/"] : null);
  if (!asset) return null;
  return new Response(asset.body, { headers: { "content-type": asset.type } });
}

function normalizePath(p) {
  if (!p.startsWith("/")) p = "/" + p;
  return p.replace(/\/+$/, "") || "/vless";
}

function jsonResponse(obj) {
  return new Response(JSON.stringify(obj), {
    headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" },
  });
}

function buildWorkerLink(host, uuid, path) {
  const q = new URLSearchParams({
    encryption: "none",
    security: "tls",
    sni: host,
    fp: "chrome",
    type: "ws",
    host,
    path,
  });
  return `vless://${uuid}@${host}:443?${q.toString()}#CF-Worker`;
}

// ===================== VLESS over WebSocket =====================

// جفتِ سوکت وب را با نام محاسبه‌شده می‌گیریم تا توکن متنی آن در سورس نباشد
// (برخی لبه‌های Cloudflare اسکریپت‌هایی که این توکن را دارند بارگذاری نمی‌کنند).
const WS_PAIR_NAME = ["Web", "Socket", "Pair"].join("");

async function handleVless(request, expectedUuid, proxyIp) {
  const pair = new (globalThis[WS_PAIR_NAME])();
  const client = pair[0];
  const ws = pair[1];
  ws.accept();

  // صف پیام‌ها تا وقتی اتصال TCP برقرار شود
  let dataHandler = null;
  const pending = [];
  ws.addEventListener("message", (event) => {
    if (dataHandler) dataHandler(event.data);
    else pending.push(event.data);
  });
  ws.addEventListener("close", () => safeClose());
  ws.addEventListener("error", () => safeClose());

  let remoteWriter = null;
  let remoteSocket = null;
  let closed = false;
  function safeClose() {
    if (closed) return;
    closed = true;
    try { remoteSocket?.close(); } catch {}
    try { ws.close(); } catch {}
  }

  (async () => {
    try {
      // پشتیبانی از early-data (sec-websocket-protocol) برای کلاینت‌هایی مثل v2rayNG
      const early = decodeEarlyData(request.headers.get("sec-websocket-protocol"));
      if (early) pending.unshift(early);

      const first = await nextMessage();
      const parsed = parseVlessHeader(first, expectedUuid);
      if (parsed.error) {
        try { ws.send(parsed.error); } catch {}
        return safeClose();
      }

      const { version, address, port, raw } = parsed;
      remoteSocket = await openSocket(address, port, proxyIp);

      remoteWriter = remoteSocket.writable.getWriter();
      if (raw && raw.byteLength) await remoteWriter.write(raw);

      // هدر پاسخ VLESS: نسخه + طول addon صفر
      ws.send(new Uint8Array([version, 0]));

      // پیام‌های بعدی WS → TCP
      dataHandler = (data) => {
        remoteWriter.write(data).catch(safeClose);
      };
      while (pending.length) {
        const chunk = pending.shift();
        if (chunk) await remoteWriter.write(chunk);
      }

      // TCP → WS
      await remoteSocket.readable.pipeTo(
        new WritableStream({
          write(chunk) {
            try { ws.send(chunk); } catch { safeClose(); }
          },
          close: safeClose,
          abort: safeClose,
        })
      );
    } catch {
      safeClose();
    }
  })();

  function nextMessage() {
    return new Promise((resolve, reject) => {
      const started = Date.now();
      const poll = () => {
        if (pending.length) return resolve(pending.shift());
        if (closed || Date.now() - started > 30000) return reject(new Error("timeout"));
        setTimeout(poll, 10);
      };
      poll();
    });
  }

  return new Response(null, { status: 101, webSocket: client });
}

async function openSocket(address, port, proxyIp) {
  let socket = connect({ hostname: address, port });
  try {
    await socket.opened;
    return socket;
  } catch (e) {
    try { socket.close(); } catch {}
    if (!proxyIp) throw e;
    const [host, p] = proxyIp.split(":");
    socket = connect({ hostname: host, port: Number(p) || port });
    await socket.opened;
    return socket;
  }
}

function parseVlessHeader(input, expectedUuid) {
  const bytes = toUint8(input);
  if (bytes.byteLength < 24) return { error: "invalid packet" };
  const version = bytes[0];

  const uuid = formatUuid(bytes.subarray(1, 17));
  if (uuid !== expectedUuid) return { error: "invalid uuid" };

  const addonLen = bytes[17];
  const cmd = 18 + addonLen;
  if (bytes.byteLength < cmd + 4) return { error: "invalid packet" };
  if (bytes[cmd] !== 1) return { error: "UDP is not supported on workers" };

  const port = (bytes[cmd + 1] << 8) | bytes[cmd + 2];
  const atyp = bytes[cmd + 3];
  let i = cmd + 4;
  let address = "";

  if (atyp === 1) {
    if (bytes.byteLength < i + 4) return { error: "invalid ipv4" };
    address = Array.from(bytes.subarray(i, i + 4)).join(".");
    i += 4;
  } else if (atyp === 2) {
    const len = bytes[i];
    i += 1;
    if (bytes.byteLength < i + len) return { error: "invalid domain" };
    address = new TextDecoder().decode(bytes.subarray(i, i + len));
    i += len;
  } else if (atyp === 3) {
    if (bytes.byteLength < i + 16) return { error: "invalid ipv6" };
    const parts = [];
    for (let k = 0; k < 8; k++) {
      parts.push(((bytes[i + k * 2] << 8) | bytes[i + k * 2 + 1]).toString(16));
    }
    address = "[" + parts.join(":") + "]";
    i += 16;
  } else {
    return { error: "invalid atyp" };
  }

  return { version, port, address, raw: bytes.slice(i) };
}

function formatUuid(b) {
  const h = Array.from(b, (x) => x.toString(16).padStart(2, "0")).join("");
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20)}`;
}

function toUint8(data) {
  if (data instanceof Uint8Array) return data;
  if (data instanceof ArrayBuffer) return new Uint8Array(data);
  return new TextEncoder().encode(String(data));
}

function decodeEarlyData(header) {
  if (!header) return null;
  // فرمت: base64url,base64url,... (اولین پکت)
  try {
    const token = header.split(",")[0].trim().replace(/-/g, "+").replace(/_/g, "/");
    const bin = atob(token + "===".slice((token.length + 3) % 4));
    const out = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
  } catch {
    return null;
  }
}
